                  <button onClick={getAutobrief} disabled={briefing} style={{padding:'10px 18px',background:'#1a1a2e',color:'#fff',border:'1px solid #333',borderRadius:'8px',cursor:'pointer',fontSize:'13px'}}>{briefing?'Writing…':'📝 Auto-Brief'}</button>
