  const tok = typeof window !== 'undefined' ? localStorage.getItem('forge_token') : '';
  const API = process.env.NEXT_PUBLIC_API_URL || 'https://forge-production-2692.up.railway.app';
          const tok = typeof window !== 'undefined' ? localStorage.getItem('forge_token') : '';
          const [doc, setDoc] = React.useState('');
