              <button onClick={async()=>{if(!disputeType||!situation)return;setLoading(true);try{const r=await fetch(`${process.env.NEXT_PUBLIC_API_URL||'https://forge-production-2692.up.railway.app'}/api/dispute/letter`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+localStorage.getItem('forge_token')},body:JSON.stringify({dispute_type:disputeType,situation,desired_outcome:desiredOutcome,recipient})});const d=await r.json();setResult(d);}catch(e){console.error(e);}setLoading(false);}} style={{width:'100%',padding:'0.875rem',background:'linear-gradient(135deg,#7c3aed,#db2777)',color:'#fff',border:'none',borderRadius:'8px',fontWeight:600,cursor:'pointer',marginBottom:'1.5rem'}}>{loading?'Writing...':'Generate Dispute Letter'}</button>
