                      <button onClick={() => setShowPersonaForm(false)} style={{ padding:'8px 14px', borderRadius:8, border:'1px solid var(--fg-border)', background:'var(--fg-bg3)', color:'var(--fg-text2)', cursor:'pointer', fontSize:13 }}>Cancel</button>
