        {(mainTab as string) === 'relcheckin' && <ForgeTab_iife_relcheckin />}

        {/* ── WAVE 17: Breakup Recovery Plan ───────────────────────── */}
        {(mainTab as string) === 'breakuprecover' && <ForgeTab_iife_breakuprecover />}

        {/* ── WAVE 17: Flirty Text Generator ───────────────────────── */}
        {(mainTab as string) === 'flirtytext' && <ForgeTab_iife_flirtytext />}

