        {(mainTab as string) === 'budgetroast' && <ForgeTab_iife_budgetroast />}

        {/* ── WAVE 18: Freelance Rate Calculator ───────────────────── */}
        {(mainTab as string) === 'freelancerate' && <ForgeTab_iife_freelancerate />}

        {/* ── WAVE 18: Investment Thesis Writer ────────────────────── */}
        {(mainTab as string) === 'invthesis' && <ForgeTab_iife_invthesis />}

        {/* ── WAVE 18: Subscription Audit ──────────────────────────── */}
        {(mainTab as string) === 'subaudit' && <ForgeTab_iife_subaudit />}

